#include <learned_recovery.h>
#include <iostream>
#include <stdexcept>
int main(int argc,char**argv){try{if(argc!=4)throw std::runtime_error("usage: model full58_features.f32 output.f32");LearnedRecoveryNetwork net;if(!net.load(argv[1]))throw std::runtime_error("model load failed");if(net.feature_size()!=28&&net.feature_size()!=58)throw std::runtime_error("expected28or58input");std::ifstream in(argv[2],std::ios::binary);std::ofstream out(argv[3],std::ios::binary);std::array<float,58> raw;size_t count=0;while(in.read(reinterpret_cast<char*>(raw.data()),sizeof(raw))){std::vector<float>x(raw.begin(),raw.begin()+net.feature_size());std::array<float,2> pred;if(!net.predict(x,pred))throw std::runtime_error("nonfinite prediction");std::array<float,2> result{{pred[0],LearnedRecoveryNetwork::probability(pred[0])}};out.write(reinterpret_cast<const char*>(result.data()),sizeof(result));++count;}if(!in.eof())throw std::runtime_error("input read failed");std::cout<<count<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
